    """
    A recursive descent parser for JSON strings. The parsing technique employs a series of functions 
    that process different JSON tokens, handling strings, numbers, booleans, null, arrays, and objects.
    """

    index = 0

    def next_token():
        nonlocal index
        while index < len(s) and s[index].isspace():
            index += 1

        if index == len(s):
            return None

        char = s[index]

        if char in '{[':
            token = char
            index += 1
            return token
        elif char in '}]':
            token = char
            index += 1
            return token
        elif char in ',:':
            token = char
            index += 1
            return token
        elif char == '"':
            index += 1
            start = index
            while index < len(s):
                if s[index] == '"':
                    break
                elif s[index] == '\\':
                    index += 2
                    continue
                index += 1
            token = s[start:index-1].replace('\\"', '"').replace('\\\\', '\\')
            index += 1
            return token
        elif char.isdigit() or char == '-':
            start = index
            while index < len(s) and (s[index].isdigit() or s[index] in '.eE+-'):
                index += 1
            token = float(s[start:index]) if '.' in s[start:index] or 'e' in s[start:index] or 'E' in s[start:index] else int(s[start:index])
            return token
        elif s.startswith('true', index):
            index += 4
            return True
        elif s.startswith('false', index):
            index += 5
            return False
        elif s.startswith('null', index):
            index += 4
            return None
        else:
            raise ValueError("Invalid JSON input")

    def parse_value():
        token = next_token()
        if token is None:
            raise ValueError("Unexpected end of input")
        elif token == '{':
            return parse_object()
        elif token == '[':
            return parse_array()
        else:
            return token

    def parse_object():
        obj = {}
        while True:
            key = next_token()
            if key == '}':
                return obj
            if not isinstance(key, str):
                raise ValueError("Expected string key in object")
            if next_token() != ':':
                raise ValueError("Expected ':' after key in object")
            value = parse_value()
            obj[key] = value
            token = next_token()
            if token == '}':
                return obj
            elif token != ',':
                raise ValueError("Expected ',' or '}' in object")

    def parse_array():
        arr = []
        while True:
            token = next_token()
            if token == ']':
                return arr
            arr.append(token)
            token = next_token()
            if token == ']':
                return arr
            elif token != ',':
                raise ValueError("Expected ',' or ']' in array")

    return parse_value()

